function icon(name, size = 18, stroke = 2) {
  const d = ICONS[name] || '';
  return `<svg class="ico" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="${stroke}" stroke-linecap="round" stroke-linejoin="round">${d}</svg>`;
}
function iconFill(name, size = 14) {
  const d = ICONS[name] || '';
  return `<svg class="ico" width="${size}" height="${size}" viewBox="0 0 24 24" fill="currentColor" stroke="none">${d}</svg>`;
}

// =====================================================
// Design helpers
// =====================================================
const LOGO_PALETTE = ['#2563EB','#7C3AED','#0D9488','#DB2777','#D97706','#0EA5E9','#65A30D','#E0454B','#4F46E5','#0891B2'];
function logoColor(seed) {
  let h = 0;
  for (let i = 0; i < seed.length; i++) h = (h * 31 + seed.charCodeAt(i)) & 0xffff;
  return LOGO_PALETTE[h % LOGO_PALETTE.length];
}
function storeLogo(name, size = 40) {
  const color = logoColor(name);
  const ch = name.replace(/^(炭火焼鳥|喫茶|和食|中華|焼肉|鉄板焼|おでん|café|BAR|Trattoria|らぁ麺|スパイス食堂)\s?/u, '').trim().charAt(0) || name.charAt(0);
  return `<div class="store-logo" style="width:${size}px;height:${size}px;font-size:${Math.round(size*0.4)}px;background:linear-gradient(155deg,${color},color-mix(in srgb,${color} 65%,#000))">${escapeHtml(ch)}</div>`;
}

function scoreRing(value, size = 38, stroke = 4) {
  const r = (size - stroke) / 2;
  const c = 2 * Math.PI * r;
  const col = value >= 80 ? 'var(--high)' : value >= 55 ? 'var(--mid)' : 'var(--low)';
  const offset = c * (1 - value / 100);
  const half = size / 2;
  return `<span class="score">
    <svg class="ring" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">
      <circle cx="${half}" cy="${half}" r="${r}" fill="none" stroke="var(--surface-3)" stroke-width="${stroke}"/>
      <circle cx="${half}" cy="${half}" r="${r}" fill="none" stroke="${col}" stroke-width="${stroke}"
        stroke-dasharray="${c.toFixed(2)}" stroke-dashoffset="${offset.toFixed(2)}" stroke-linecap="round"
        transform="rotate(-90 ${half} ${half})"/>
    </svg>
    <span class="sv">${value}</span>
  </span>`;
}

function donut(pct) {
  const r = 40, c = 2 * Math.PI * r;
  return `<svg class="donut" viewBox="0 0 96 96">
    <circle cx="48" cy="48" r="${r}" fill="none" stroke="var(--surface-3)" stroke-width="10"/>
    <circle cx="48" cy="48" r="${r}" fill="none" stroke="var(--brand)" stroke-width="10" stroke-linecap="round"
      stroke-dasharray="${c.toFixed(2)}" stroke-dashoffset="${(c*(1-pct/100)).toFixed(2)}" transform="rotate(-90 48 48)"/>
    <text x="48" y="46" text-anchor="middle" font-family="var(--font-num)" font-weight="700" font-size="22" fill="var(--ink)">${pct}%</text>
    <text x="48" y="62" text-anchor="middle" font-family="var(--font-jp)" font-size="9.5" fill="var(--muted)">完了</text>
  </svg>`;
}

const PRIORITY_META = {
  high:   { label: '高', cls: 'badge-high', color: 'var(--high)' },
  medium: { label: '中', cls: 'badge-mid',  color: 'var(--mid)' },
  mid:    { label: '中', cls: 'badge-mid',  color: 'var(--mid)' },
  low:    { label: '低', cls: 'badge-low',  color: 'var(--low)' },
};
function priorityBadge(p) {
  const meta = PRIORITY_META[p] || PRIORITY_META.low;
  return `<span class="badge ${meta.cls}"><span class="bd" style="background:${meta.color}"></span>優先度 ${meta.label}</span>`;
}

