  profile_basic:   { label: '基本情報整備',color: 'var(--t-basic)',  bg: 'var(--t-basic-bg)', desc: '営業時間・写真・メニュー等の情報が不足しています。' },
};
function issueTag(key) {
  const t = ISSUES[key];
  if (!t) return '';
  return `<span class="tag" style="background:${t.bg};color:${t.color}">${t.label}</span>`;
}
function issueTagsHtml(keys, max = 3) {
  const tags = (keys || []).slice(0, max).map(k => issueTag(k)).join('');
  const extra = (keys || []).length > max ? `<span class="tag" style="background:var(--surface-3);color:var(--muted)">+${keys.length - max}</span>` : '';
  return tags + extra;
}

