// =====================================================
// Navigation
// =====================================================
function go(screen, storeId = null) {
  syncCollectFormState();
  syncDbFilterState();
  currentScreen = screen;
  currentStoreId = storeId || null;
  try { localStorage.setItem('rsi_nav', JSON.stringify({ screen: currentScreen, storeId: currentStoreId })); } catch (e) {}
  renderApp();
}

function syncCollectFormState() {
  const area = document.getElementById('collect-area-input');
  if (area) collectArea = area.value;
  const target = document.getElementById('collect-campaign-target');
  if (target) collectTarget = Number(target.value) || collectTarget;
  const batch = document.getElementById('collect-campaign-batch-size');
  if (batch) collectBatchSize = Number(batch.value) || collectBatchSize;
  const maxC = document.getElementById('collect-campaign-max-collected');
  if (maxC) collectMaxCollected = Number(maxC.value) || collectMaxCollected;
  const maxA = document.getElementById('collect-campaign-max-api-calls');
  if (maxA) collectMaxApiCalls = Number(maxA.value) || collectMaxApiCalls;
}

function syncDbFilterState() {
  const q = document.getElementById('db-search-q');
  if (q) dbQ = q.value;
  const sort = document.getElementById('db-sort-select');
  if (sort) dbSort = sort.value;
}

function renderApp() {
  updateSidebar();
  updateTopbar();
  const content = document.getElementById('screen-content');
  if (!content) return;
  if (currentScreen === 'dashboard') {
    content.innerHTML = renderDashboard();
    attachDashboardListeners();
  } else if (currentScreen === 'collect') {
    content.innerHTML = renderCollect();
    attachCollectListeners();
  } else if (currentScreen === 'database') {
    content.innerHTML = renderDatabaseScreen();
    attachDatabaseListeners();
  } else if (currentScreen === 'detail') {
    const lead = currentStoreId ? leads.find(l => l.id === currentStoreId) : leads[0];
    content.innerHTML = renderDetailScreen(lead);
    attachDetailListeners(lead);
  }
}

function updateSidebar() {
  ['dashboard', 'collect', 'database'].forEach(s => {
    const el = document.getElementById(`nav-${s}`);
    if (!el) return;
    const isActive = currentScreen === s || (currentScreen === 'detail' && s === 'database');
    el.classList.toggle('active', isActive);
  });
  const badge = document.getElementById('nav-db-count');
  if (badge) badge.textContent = leads.length > 0 ? String(leads.length) : '';
}

function updateTopbar() {
  const crumb = document.getElementById('topbar-crumb');
  if (!crumb) return;
  const detailName = currentStoreId ? (leads.find(l => l.id === currentStoreId)?.displayName || '店舗分析') : '店舗分析';
  const map = {
    dashboard: '<div class="crumb"><b>ダッシュボード</b></div>',
    collect:   '<div class="crumb"><b>エリア収集</b></div>',
    database:  '<div class="crumb"><b>店舗データベース</b></div>',
    detail:    `<div class="crumb"><button class="btn btn-sm btn-ghost" id="crumb-back-btn" style="padding:4px 8px">${icon('chevR', 14, 2.5)} データベース</button><span class="sep">/</span><b>${escapeHtml(detailName)}</b></div>`,
  };
  crumb.innerHTML = map[currentScreen] || '';
  document.getElementById('crumb-back-btn')?.addEventListener('click', () => go('database'));
}

