function renderPStep({ n, done, active, title, iconName, desc, metric, unit, pct, cta, targetScreen }) {
  return `<div class="pstep${done ? ' done' : ''}">
    <div style="display:flex;align-items:center;gap:11px;margin-bottom:12px">
      <span class="pnum">${done ? icon('check', 16, 3) : n}</span>
      ${icon(iconName, 18)}
      <span class="ptitle">${title}</span>
    </div>
    <div class="pdesc">${desc}</div>
    <div class="pmetric num">${metric}<small>${unit}</small></div>
    <div class="pbar"><i style="width:${pct}%;background:${done ? 'var(--good)' : 'var(--brand)'}"></i></div>
    <button class="btn btn-sm${active ? ' btn-primary' : ''}" data-goto="${targetScreen}" style="margin-top:14px;width:fit-content">${cta}${icon('arrowR', 14)}</button>
  </div>`;
}

function renderStatCard({ iconName, iconColor, iconBg, label, value, unit = '', delta = '', deltaType = 'up' }) {
  return `<div class="stat">
    <div class="label">
      <span class="chip-ico" style="background:${iconBg};color:${iconColor}">${icon(iconName, 15)}</span>
      ${label}
    </div>
    <div class="val num">${value}${unit ? `<small>${unit}</small>` : ''}</div>
    ${delta ? `<span class="delta ${deltaType}">${deltaType === 'up' ? icon('trend', 12, 2.6) : ''}${delta}</span>` : ''}
  </div>`;
}

function leadScore(lead) {
  const p = lead.analysis?.priority;
  if (p === 'high') return 82;
  if (p === 'medium') return 65;
  return 40;
}

function attachDashboardListeners() {
  document.getElementById('dash-collect-btn')?.addEventListener('click', () => go('collect'));
  document.getElementById('dash-view-all-btn')?.addEventListener('click', () => go('database'));
  document.querySelectorAll('.dash-lead-row').forEach(row => {
    row.addEventListener('click', () => go('detail', row.dataset.leadId));
  });
  document.querySelectorAll('[data-goto]').forEach(btn => {
    btn.addEventListener('click', () => go(btn.dataset.goto));
  });
}

