function getFilteredLeads() {
  let r = [...leads];
  if (dbPrio !== 'all') {
    r = r.filter(l => {
      const p = l.analysis?.priority;
      if (dbPrio === 'mid') return p === 'medium' || p === 'mid';
      return p === dbPrio;
    });
  }
  if (dbIssue !== 'all') r = r.filter(l => (l.analysis?.issueTags || []).includes(dbIssue));
  if (dbQ) {
    const q = dbQ.toLowerCase();
    r = r.filter(l => l.displayName?.toLowerCase().includes(q) || l.formattedAddress?.toLowerCase().includes(q));
  }
  if (dbSort === 'score') r.sort((a, b) => (priorityWeight[b.analysis?.priority] || 0) - (priorityWeight[a.analysis?.priority] || 0));
  else if (dbSort === 'rating') r.sort((a, b) => (a.rating || 0) - (b.rating || 0));
  return r;
}

