  });

  document.getElementById('detail-regen-btn')?.addEventListener('click', async () => {
    if (lead) await generateLeadOutreach(lead.id);
  });

  document.querySelectorAll('[data-action="draft-status"]').forEach(btn => {
    btn.addEventListener('click', () => updateOutreachStatus(
      btn.getAttribute('data-lead-id'),
      btn.getAttribute('data-draft-id'),
      btn.getAttribute('data-status')
    ));
  });
}

// =====================================================
// API functions (preserved from original)
// =====================================================
async function collect() {
  setLoading(true);
  setNotices([]);
  try {
    const response = await fetch('/api/collect', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        location: collectArea,
        query: collectGenres.join(' ') || 'レストラン',
        limit: collectCount
      })
    });
    const json = await response.json();
    if (!response.ok) throw new Error(json.hint || json.error || '収集に失敗しました');
    leads = json.leads || [];
    selectedId = leads[0]?.id || null;
    currentMode = 'database';
    leadPage.cursor = '';
    leadPage.hasMore = false;
    setNotices([
      `${json.collected || 0}件を収集し、${json.inserted || 0}件を新規保存、${json.updated || 0}件を更新しました。`,
      ...(json.warnings || [])
    ]);
    renderApp();
  } catch (error) {
    setNotices([error.message || '収集に失敗しました'], true);
  } finally {
    setLoading(false);
  }
}

async function loadDatabase({ append = false, reset = false } = {}) {
  setLoading(true);
  setNotices([]);
  try {
    if (reset) {
      leadPage.offset = 0;
      leadPage.cursor = '';
    }
    const params = new URLSearchParams();
    params.set('area', collectArea);
    params.set('limit', String(leadPage.limit));
    if (append && leadPage.cursor) params.set('cursor', leadPage.cursor);
    else if (append) params.set('offset', String(leadPage.offset + leads.length));
    if (dbQ.trim()) params.set('q', dbQ.trim());
    if (dbPrio !== 'all') params.set('priority', dbPrio);
    if (dbIssue !== 'all') params.set('issue', dbIssue);
    const response = await fetch(`/api/leads?${params.toString()}`);
    const json = await response.json();
    if (!response.ok) throw new Error(json.hint || json.error || 'DB読み込みに失敗しました');
    leads = append ? mergeLeads(leads, json.leads || []) : (json.leads || []);
    leadPage.offset = Number(json.filters?.offset || 0);
    leadPage.limit = Number(json.filters?.limit || leadPage.limit);
    leadPage.cursor = json.nextCursor || '';
    leadPage.hasMore = Boolean(json.hasMore);
    selectedId = append ? (selectedId || leads[0]?.id || null) : (leads[0]?.id || null);
    currentMode = 'database';
    const notices = [];
    if (json.hasMore) notices.push(`${leads.length}件を表示中です。「さらに表示」で続きの候補を確認できます。`);
    if (json.storage && !json.storage.persistent) notices.push(json.storage.warning);
    if (notices.length) setNotices(notices);
    renderApp();
  } catch (error) {
    setNotices([error.message || 'DB読み込みに失敗しました'], true);
  } finally {
    setLoading(false);
  }
}

function mergeLeads(current, next) {
  const seen = new Set(current.map(l => l.id));
  return [...current, ...next.filter(l => {
    if (seen.has(l.id)) return false;
    seen.add(l.id);
    return true;
  })];
}

function setLoading(value) {
  const btn = document.getElementById('collect-search-btn');
  if (btn) { btn.disabled = value; btn.textContent = value ? '収集中...' : '検索して保存'; }
}

function setCampaignLoading(value) {
  const sel = selectedCampaign();
  ['collect-campaign-start-btn', 'collect-run-once-btn', 'collect-stop-btn', 'collect-generate-outreach-btn'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.disabled = value || (id === 'collect-run-once-btn' && !selectedCampaignId) || (id === 'collect-stop-btn' && !selectedCampaignId);
  });
  const genBtn = document.getElementById('collect-generate-outreach-btn');
  if (genBtn) genBtn.disabled = value || !canGenerateCampaignOutreach(sel);
}

async function startCampaign() {
  setCampaignLoading(true);
  setNotices([]);
  try {
    const seeds = collectGenres.length > 0 ? collectGenres.join('\n') : 'レストラン\n居酒屋\nカフェ\n焼肉\nラーメン\nイタリアン';
    const response = await fetch('/api/campaigns', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        location: collectArea,
        targetQualified: collectTarget,
        maxCollected: collectMaxCollected,
        batchSize: collectBatchSize,
        maxApiCalls: collectMaxApiCalls,
        seedKeywords: seeds
      })
    });
    const json = await response.json();
    if (!response.ok) throw new Error(json.hint || json.error || 'キャンペーン開始に失敗しました');
    selectedCampaignId = json.campaign.id;
    setNotices([`キャンペーンを開始しました: ${json.campaign.name}`, ...(json.warnings || [])]);
    await loadCampaigns();
  } catch (error) {
    setNotices([error.message || 'キャンペーン開始に失敗しました'], true);
  } finally {
    setCampaignLoading(false);
  }
}

async function loadCampaigns() {
  try {
    const response = await fetch('/api/campaigns');
    const json = await response.json();
    if (!response.ok) throw new Error(json.hint || json.error || 'キャンペーン読み込みに失敗しました');
    campaigns = json.campaigns || [];
    if (!selectedCampaignId && campaigns[0]) selectedCampaignId = campaigns[0].id;
    if (currentScreen === 'collect') {
      const content = document.getElementById('screen-content');
      if (content) { content.innerHTML = renderCollect(); attachCollectListeners(); }
    }
    updateSidebar();
  } catch (error) {
    setNotices([error.message || 'キャンペーン読み込みに失敗しました'], true);
  }
}

async function runSelectedCampaign() {
  if (!selectedCampaignId) return;
  setCampaignLoading(true);
  try {
    const response = await fetch('/api/campaigns/run', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ campaignId: selectedCampaignId })
    });
    const json = await response.json();
    if (!response.ok) throw new Error(json.hint || json.error || 'batch実行に失敗しました');
    if (json.ran) {
      setNotices([`${json.query} を1回確認: ${json.collected || 0}件を保存対象、見込み客 ${json.qualified || 0}件、重複除外 ${json.duplicateSkipped || 0}件`]);
    } else if (json.reason) {
      setNotices([`今回は実行されませんでした: ${translateRunReason(json.reason)}`]);
    }
    await loadCampaigns();
    await loadDatabase();
    stopAutoRunIfDone(json.campaign);
  } catch (error) {
    setNotices([error.message || 'batch実行に失敗しました'], true);
    const ar = document.getElementById('campaign-auto-run');
    if (ar) ar.checked = false;
    toggleCampaignAutoRun();
  } finally {
    setCampaignLoading(false);
  }
}

async function stopSelectedCampaign() {
  if (!selectedCampaignId) return;
  const ar = document.getElementById('campaign-auto-run');
  if (ar) ar.checked = false;
  toggleCampaignAutoRun();
  try {
    const response = await fetch('/api/campaigns/stop', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ campaignId: selectedCampaignId })
    });
    const json = await response.json();
    if (!response.ok) throw new Error(json.hint || json.error || '停止に失敗しました');
    setNotices([`キャンペーンを停止しました: ${json.campaign.name}`]);
    await loadCampaigns();
  } catch (error) {
    setNotices([error.message || '停止に失敗しました'], true);
  }
}

async function showQualifiedLeads() {
  if (!selectedCampaignId) return;
  try {
    const params = new URLSearchParams({ id: selectedCampaignId, qualified: '1' });
    const response = await fetch(`/api/campaigns?${params.toString()}`);
    const json = await response.json();
    if (!response.ok) throw new Error(json.hint || json.error || 'qualified一覧に失敗しました');
    leads = json.leads || [];
    selectedId = leads[0]?.id || null;
    currentMode = 'database';
    setNotices([`${json.campaign.name}: 見込み客 ${leads.length}件を表示中`]);
    renderApp();
  } catch (error) {
    setNotices([error.message || 'qualified一覧に失敗しました'], true);
  }
}

async function generateCampaignOutreach() {
  if (!selectedCampaignId) return;
  setCampaignLoading(true);
  try {
    const response = await fetch('/api/outreach', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'generate', campaignId: selectedCampaignId, qualifiedOnly: true, limit: 25 })
    });
    const json = await response.json();
    if (!response.ok) throw new Error(json.error || '提案文の生成に失敗しました');
    const pendingBefore = Number(json.pending || 0);
    const generated = Number(json.generated || 0);
    const skippedExisting = Number(json.skippedExisting || 0);
    const remaining = Math.max(0, pendingBefore - generated);
    const more = json.hasMore ? ' 続きはもう一度「提案文をまとめて生成」を押してください。' : '';
    setNotices([`見込み客 ${generated}件に連絡手段と提案文下書きを保存しました。対象 ${json.matched || generated}件、既存下書き ${skippedExisting}件、未生成残り ${remaining}件です。実送信はしていません。${more}`]);
    await showQualifiedLeads();
  } catch (error) {
    setNotices([error.message || '提案文の生成に失敗しました'], true);
  } finally {
    setCampaignLoading(false);
  }
}

function toggleCampaignAutoRun() {
  if (campaignTimer) { clearInterval(campaignTimer); campaignTimer = null; }
  const ar = document.getElementById('campaign-auto-run');
  if (ar?.checked) {
    campaignTimer = setInterval(() => runSelectedCampaign(), 5000);
    runSelectedCampaign();
  }
}

function stopAutoRunIfDone(campaign) {
  if (!campaign || campaign.status === 'running') return;
  const ar = document.getElementById('campaign-auto-run');
  if (ar) ar.checked = false;
  toggleCampaignAutoRun();
}

function renderCampaigns(storage = {}) {
  // Called for legacy compatibility; in new UI we re-render the collect screen
  if (currentScreen === 'collect') {
    const content = document.getElementById('screen-content');
    if (content) { content.innerHTML = renderCollect(); attachCollectListeners(); }
  }
}

function campaignStatusText(campaign, storage = {}) {
  if (!campaign) return storageText(storage);
  const query = campaign.cursor?.currentQuery || campaign.seeds?.[campaign.cursor?.seedIndex] || '-';
  return [
    `状態=${statusText(campaign.status)}`,
    `見込み客=${campaign.stats?.qualified || 0}/${campaign.targetQualified}`,
    `確認済み=${campaign.stats?.collected || 0}/${campaign.maxCollected}`,
    `API実行=${campaign.stats?.apiCalls || 0}/${campaign.maxApiCalls}`,
    outreachStatusText(campaign),
    `次の業種=${query}`
  ].filter(Boolean).join(' / ');
}

function selectedCampaign() {
  return campaigns.find(c => c.id === selectedCampaignId) || null;
}

function canGenerateCampaignOutreach(campaign) {
  if (!campaign) return false;
  const stats = campaign.outreachStats;
  return !(stats && stats.matched > 0 && stats.pending === 0);
}

function outreachStatusText(campaign) {
  const stats = campaign?.outreachStats;
  if (!stats) return '提案文=未確認';
  if (!stats.matched) return '提案文=見込み客なし';
  return `提案文=未生成${stats.pending}/対象${stats.matched}`;
}

async function generateLeadOutreach(leadId) {
  try {
    const response = await fetch('/api/outreach', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'generate', leadId })
    });
    const json = await response.json();
    if (!response.ok) throw new Error(json.error || '提案文の生成に失敗しました');
    const updated = json.leads?.[0];
    if (updated) replaceLead(updated);
    setNotices(['連絡手段と提案文下書きを保存しました。実送信はしていません。']);
  } catch (error) {
    setNotices([error.message || '提案文の生成に失敗しました'], true);
  }
}

async function updateOutreachStatus(leadId, draftId, status) {
  try {
    const response = await fetch('/api/outreach', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ action: 'status', leadId, draftId, status })
    });
    const json = await response.json();
    if (!response.ok) throw new Error(json.error || '状態更新に失敗しました');
    replaceLead(json.lead);
    setNotices(['送信キューの状態を更新しました。外部送信はしていません。']);
  } catch (error) {
    setNotices([error.message || '状態更新に失敗しました'], true);
  }
}

function replaceLead(lead) {
  leads = leads.map(item => item.id === lead.id ? lead : item);
  currentStoreId = lead.id;
  if (currentScreen === 'detail') {
    const content = document.getElementById('screen-content');
    if (content) { content.innerHTML = renderDetailScreen(lead); attachDetailListeners(lead); }
  }
}

function renderChannels(lead) {
  const channels = lead.contactChannels || [];
  if (!channels.length) return '<p class="muted-text">まだ連絡手段を生成していません。</p>';
  return `<div class="contact-list">${channels.map(ch => `
    <div class="contact-row">
      <strong>${escapeHtml(ch.label)}</strong>
      <span>${escapeHtml(ch.type)} / ${escapeHtml(ch.status)} / 信頼度 ${Math.round((ch.confidence || 0) * 100)}%</span>
      <small>${escapeHtml(ch.value || ch.url || '')}</small>
      ${ch.notes ? `<small>${escapeHtml(ch.notes)}</small>` : ''}
    </div>`).join('')}</div>`;
}

function renderApproachPlan(lead) {
  const plan = lead.approachPlan || [];
  if (!plan.length) return '<p class="muted-text" style="margin-top:8px">提案文を作成するとおすすめ順が表示されます。</p>';
  return `<ol class="approach-list" style="margin-top:8px">${plan.map(item => `
    <li><strong>${item.rank}. ${escapeHtml(item.label)}</strong><span>${escapeHtml(item.reason)}</span></li>
  `).join('')}</ol>`;
}

function renderDrafts(lead) {
  const drafts = lead.outreach?.drafts || [];
  if (!drafts.length) return '<p class="muted-text" style="margin-top:8px">まだ下書きはありません。「提案文を作成」を押してください。</p>';
  return drafts.map(draft => `
    <div class="draft-card">
      <div class="draft-head">
        <strong>${escapeHtml(draft.title || draft.typeLabel)}</strong>
        <span class="tag" style="background:var(--brand-tint);color:var(--brand-strong)">${escapeHtml(draft.statusLabel || draft.status)}</span>
      </div>
      ${draft.subject ? `<p style="margin-top:8px;font-size:13px"><b>件名:</b> ${escapeHtml(draft.subject)}</p>` : ''}
      <p style="margin-top:8px;font-size:13px;line-height:1.8;color:var(--ink-2)">${escapeHtml(draft.body)}</p>
      <div class="draft-actions">
        <button class="mini-button" data-action="draft-status" data-lead-id="${escapeAttr(lead.id)}" data-draft-id="${escapeAttr(draft.id)}" data-status="needs_review">承認待ちにする</button>
        <button class="mini-button" data-action="draft-status" data-lead-id="${escapeAttr(lead.id)}" data-draft-id="${escapeAttr(draft.id)}" data-status="approved">送信準備にする</button>
        <button class="mini-button" data-action="draft-status" data-lead-id="${escapeAttr(lead.id)}" data-draft-id="${escapeAttr(draft.id)}" data-status="sent">送信済みに手動でマーク</button>
        <button class="mini-button" data-action="draft-status" data-lead-id="${escapeAttr(lead.id)}" data-draft-id="${escapeAttr(draft.id)}" data-status="skipped">スキップ</button>
      </div>
    </div>`).join('');
}

// =====================================================
// Helpers
// =====================================================
function setNotices(messages, isError = false) {
  const bar = document.getElementById('notices-bar');
  if (!bar) return;
  bar.innerHTML = messages.filter(Boolean).map(m =>
    `<div class="notice ${isError ? 'error' : ''}">${escapeHtml(m)}</div>`
  ).join('');
}

function setStorageStatus(msg) {
  // storage status is shown in notices in new UI
  if (msg) setNotices([msg]);
}

function storageText(storage = {}) {
  if (!storage.mode) return '保存DBの状態を確認できません。';
  if (storage.persistent) return `保存DB: ${storage.mode} storeで永続化中`;
  return `保存DB: ${storage.mode} storeで一時保存中`;
}

function statusText(status) {
  return campaignStatusLabel[status] || status || '未設定';
}

function translateRunReason(reason) {
  return String(reason || '')
    .replace('delay window is still active', '待機時間中です')
    .replace('target qualified count reached', '目標見込み客数に達しました')
    .replace('max collected reached', '最大確認店舗数に達しました')
    .replace('max API calls reached', '最大API実行回数に達しました')
    .replace('seed queries exhausted', '業種キーワードを確認し終えました');
}

function sortedLeads() {
  return [...leads].sort((a, b) => {
    if (sortKey === 'priority') return (priorityWeight[b.analysis?.priority] || 0) - (priorityWeight[a.analysis?.priority] || 0);
    if (sortKey === 'rating') return (a.rating || 0) - (b.rating || 0);
    return (a.userRatingCount || 0) - (b.userRatingCount || 0);
  });
}

function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' })[c]);
}

function escapeAttr(value) {
  return escapeHtml(value).replace(/`/g, '&#096;');
}

// =====================================================
// Init
// =====================================================

// Restore nav from localStorage
try {
  const saved = JSON.parse(localStorage.getItem('rsi_nav') || '{}');
  if (saved.screen) currentScreen = saved.screen;
  if (saved.storeId) currentStoreId = saved.storeId;
} catch (e) {}

// Sidebar nav click
document.querySelectorAll('.nav-item[data-screen]').forEach(btn => {
  btn.addEventListener('click', () => go(btn.dataset.screen));
});

// Topbar search
document.getElementById('topbar-search-input')?.addEventListener('keydown', async e => {
  if (e.key === 'Enter') {
    dbQ = e.target.value;
    go('database');
    await loadDatabase({ reset: true });
  }
});

// Initial render then load data
renderApp();
loadDatabase({ reset: true }).catch(() => {});
loadCampaigns().catch(() => {});

