import { access, readdir, readFile } from 'node:fs/promises';
import { join } from 'node:path';

const required = [
  'public/index.html',
  'public/app.js',
  'public/styles.css',
  'public/sample-leads.json',
  'api/search.js',
  'api/collect.js',
  'api/leads.js',
  'api/campaigns.js',
  'api/campaigns-run.js',
  'api/campaigns-stop.js',
  'api/outreach.js',
  'lib/analysis.mjs',
  'lib/campaign-criteria.mjs',
  'lib/campaign-runner.mjs',
  'lib/campaign-store.mjs',
  'lib/google-places.mjs',
  'lib/lead-store.mjs',
  'lib/outreach.mjs',
  'lib/outreach-providers.mjs',
  'lib/providers.mjs',
  'vercel.json',
  'README.md',
  'OPERATIONS.md',
  '.env.example',
  '.env.supabase.example',
  'docs/persistence-supabase.md',
  'docs/vercel-env.supabase.template',
  'db/schema.sql'
];

for (const path of required) {
  await access(path);
}

const app = await readFile('public/app.js', 'utf8');
if (!app.includes('/api/collect') || !app.includes('/api/leads')) {
  throw new Error('public/app.js does not reference the saved database workflow');
}

if (!app.includes('/api/campaigns') || !app.includes('campaign-auto-run')) {
  throw new Error('public/app.js does not reference the campaign workflow');
}

if (!app.includes('/api/outreach') || !app.includes('提案文を作成') || !app.includes('実送信はしていません')) {
  throw new Error('public/app.js does not expose the safe outreach workflow');
}

const api = await readFile('api/search.js', 'utf8');
if (!api.includes('GOOGLE_MAPS_API_KEY') || !api.includes('searchRestaurantsWithPlaces')) {
  throw new Error('api/search.js is missing Places API integration');
}

const collectApi = await readFile('api/collect.js', 'utf8');
if (!collectApi.includes('createLeadStore') || !collectApi.includes('createPlacesProvider')) {
  throw new Error('api/collect.js is missing storage/provider integration');
}

const campaignApi = await readFile('api/campaigns-run.js', 'utf8');
if (!campaignApi.includes('runCampaignBatch') || !campaignApi.includes('createCampaignStore')) {
  throw new Error('api/campaigns-run.js is missing campaign batch integration');
}

const outreachApi = await readFile('api/outreach.js', 'utf8');
if (!outreachApi.includes('dryRunSend') || !outreachApi.includes('sendEnabled: false')) {
  throw new Error('api/outreach.js must keep real sending disabled');
}

const store = await readFile('lib/lead-store.mjs', 'utf8');
if (!store.includes('PostgresLeadStore') || !store.includes('restaurant_leads')) {
  throw new Error('lib/lead-store.mjs is missing the Postgres persistence adapter');
}

const campaignStore = await readFile('lib/campaign-store.mjs', 'utf8');
if (!campaignStore.includes('PostgresCampaignStore') || !campaignStore.includes('collection_campaigns')) {
  throw new Error('lib/campaign-store.mjs is missing the Postgres campaign adapter');
}

const persistenceGuide = await readFile('docs/persistence-supabase.md', 'utf8');
if (!persistenceGuide.includes('Production Preflight Checklist') || !persistenceGuide.includes('Supabase Free Postgres')) {
  throw new Error('docs/persistence-supabase.md is missing the production persistence checklist');
}

if (!persistenceGuide.includes('Rollback Plan') || !persistenceGuide.includes('Work Split')) {
  throw new Error('docs/persistence-supabase.md is missing rollback or work split guidance');
}

const publicFiles = await readdir(join(process.cwd(), 'public'));
console.log(`Build check passed. Static files: ${publicFiles.join(', ')}`);

